// Sun-tracking solar panel: single axis, swings east-west with the local solar hour.
// Sunlight at the top of the atmosphere: fact(FACT_MARS_SOLAR_CONSTANT_MEAN) [mars.solar.constant_mean].
// Dust: clear-season fact by default, storm fact when signal 200 reads 1.
// ASSUMPTIONS (not facts): area 2 m2 and 25% efficiency (player); sun on the equator,
// i.e. equinox (the world clock has no season); the direct beam fades as exp(-tau / cos zenith);
// half the light the dust scatters still reaches the ground, evenly from the whole sky (DIFFUSE_K).
import { read, fact, spawn, pose, state_set, signal_emit, signal_read, log, ENV_LOCAL_HOUR, HEADING,
         SHAPE_CYLINDER, SHAPE_BOX, FACT_MARS_SOLAR_CONSTANT_MEAN,
         FACT_JEZERO_DUST_OPTICAL_DEPTH_BACKGROUND_MY36, FACT_JEZERO_DUST_OPTICAL_DEPTH_STORM_JAN2022 } from "./host";

const AREA_M2: f32 = 2.0;          // player's assumption
const EFF: f32 = 0.25;             // player's assumption
const DIFFUSE_K: f32 = 0.5;        // design assumption: scattered share reaching the ground
const LAT_DEG: f32 = 18.0;         // Jezero, about 18 N [jezero.location.landing_site]; table record, fact() cannot read it
const SIG_STORM: i32 = 200;        // listens: 1 = storm sky
const SIG_POWER: i32 = 201;        // emits: output in W, every tick
const LOG_HOUR_W: i32 = 1;         // log code 1: output (W) at each new hour
const LOG_MODE: i32 = 2;           // log code 2: mode changed, 1 tracking / 0 parked flat
const DEG: f32 = 57.29578;         // radians to degrees (geometry, not Mars)

let post: i32 = -1, panel: i32 = -1;
let lastHour: i32 = -1, lastMode: i32 = -1;
let s0: f32 = 0, tauClear: f32 = 0, tauStorm: f32 = 0, cosLat: f32 = 1;

export function init(): void {
  s0 = fact(FACT_MARS_SOLAR_CONSTANT_MEAN);                         // W/m^2
  tauClear = fact(FACT_JEZERO_DUST_OPTICAL_DEPTH_BACKGROUND_MY36);
  tauStorm = fact(FACT_JEZERO_DUST_OPTICAL_DEPTH_STORM_JAN2022);
  cosLat = Mathf.cos(LAT_DEG / DEG);
  post = spawn(SHAPE_CYLINDER, 0.1, 1.2, 0.1, 0.6, 0.6, 0.6);
  pose(post, 0.0, 0.6, 0.0, 0.0, 0.0);
  panel = spawn(SHAPE_BOX, 1.0, 0.05, 2.0, 0.1, 0.15, 0.45);       // 1 m N-S by 2 m E-W = 2 m2
}

export function tick(dt: f32): void {
  const hour = read(ENV_LOCAL_HOUR);
  const h: f32 = (hour - 12.0) * (Mathf.PI / 12.0);   // hour angle: 24 solar hours per turn
  const sE: f32 = -Mathf.sin(h);                      // sun's east component (morning > 0)
  const sUp: f32 = cosLat * Mathf.cos(h);             // cos(zenith), equinox sun
  const tau: f32 = signal_read(SIG_STORM) == 1.0 ? tauStorm : tauClear;

  let beam: f32 = 0.0, diff: f32 = 0.0;
  if (sUp > 0.01) {
    const t = Mathf.exp(-tau / sUp);                  // beam transmission (assumption)
    beam = s0 * t;                                    // W/m^2 facing the sun
    diff = DIFFUSE_K * s0 * sUp * (1.0 - t);          // W/m^2 on flat ground, whole sky
  }
  // Best east-west tilt, and what it gains versus lying flat. Tilting sees less sky.
  const rho: f32 = sUp > 0.01 ? Mathf.atan2(sE, sUp) : 0.0;
  const gTrack: f32 = beam * Mathf.sqrt(sE * sE + sUp * sUp) + diff * (1.0 + Mathf.cos(rho)) * 0.5;
  const gFlat: f32 = beam * (sUp > 0.0 ? sUp : 0.0) + diff;
  const track: i32 = (sUp > 0.01 && gTrack > gFlat) ? 1 : 0;
  const tilt: f32 = track == 1 ? rho : 0.0;
  const g: f32 = track == 1 ? gTrack : gFlat;
  const watts: f32 = g * AREA_M2 * EFF;

  // Face the shape east in the world, then pitch about its north-south axis.
  pose(panel, 0.0, 1.25, 0.0, -Mathf.PI * 0.5 - read(HEADING), tilt);

  state_set(0, watts);
  state_set(1, tilt * DEG);
  state_set(2, sUp > 0.0 ? Mathf.asin(sUp) * DEG : 0.0);
  state_set(3, tau);
  state_set(4, <f32>track);
  state_set(5, g);
  signal_emit(SIG_POWER, watts);

  const hr = <i32>Mathf.floor(hour);
  if (hr != lastHour) { lastHour = hr; log(LOG_HOUR_W, watts); }
  if (track != lastMode) { lastMode = track; log(LOG_MODE, <f32>track); }
}

