log.manifestText:
{
  "name": "sun-tracking solar panel",
  "description": "A 2 m2 panel on a post that swings east to west with the local solar hour and reports its electrical output. Clear-season dust by default; emit signal 200 = 1 for storm sky, and it parks flat whenever flat collects more.",
  "version": 1,
  "author": "design agent",
  "state": [
    { "slot": 0, "label": "electrical output", "unit": "W" },
    { "slot": 1, "label": "panel tilt (+ east, - west)", "unit": "deg" },
    { "slot": 2, "label": "sun elevation (equinox assumption)", "unit": "deg" },
    { "slot": 3, "label": "dust optical depth in use", "unit": "1" },
    { "slot": 4, "label": "tracking (1) or parked flat (0)", "unit": "flag" },
    { "slot": 5, "label": "sunlight on panel", "unit": "W/m^2" }
  ],
  "signals": {
    "emits": [ { "code": 201, "label": "panel output", "unit": "W" } ],
    "listens": [ { "code": 200, "label": "storm sky (1 = storm)", "unit": "flag" } ]
  },
  "shapes": 2,
  "fact_ids": [
    "mars.solar.constant_mean",
    "jezero.dust.optical_depth_background_my36",
    "jezero.dust.optical_depth_storm_jan2022",
    "jezero.location.landing_site"
  ],
  "did_you_know": {
    "text": "During the January 2022 regional dust storm at Jezero, the sky's dust optical depth peaked near 2, about five times the clear-season value of roughly 0.4.",
    "fact_id": "jezero.dust.optical_depth_storm_jan2022"
  }
}
